  async initialize(context) {
    this.registerHook('log', async (data) => {
      console.log(`[${new Date().toISOString()}] ${data.message}`, data.meta);
      return data;
    });
  }
}

/**
 * Analytics Plugin - 분석
 */
class AnalyticsPlugin extends Plugin {
  constructor() {
    super('analytics', '1.0.0');
    this.events = [];
