   */
  setTypography(typography) {
    this.typography = typography;
  }

  /**
   * 여백 설정
   */
  setSpacing(spacing) {
    this.spacing = spacing;
  }

  /**
   * 그림자 설정
   */
  setShadows(shadows) {
    this.shadows = shadows;
  }

  /**
   * 테마를 CSS 변수로 변환
   */
  toCSSVariables() {
    const variables = {};

    // 색상
    for (const [key, value] of Object.entries(this.colors)) {
      variables[`--${key}`] = value;
    }

    // 타이포그래피
