    }

    // 그림자
    for (const [key, value] of Object.entries(this.shadows)) {
      variables[`--shadow-${key}`] = value;
    }

    return variables;
  }

  /**
   * CSS 문자열 생성
   */
  generateCSS() {
    const variables = this.toCSSVariables();
    let css = ':root {\n';

    for (const [key, value] of Object.entries(variables)) {
      css += `  ${key}: ${value};\n`;
    }

    css += '}';
    return css;
  }
}

