const DesignCompiler = require('./design-compiler');

let testsPassed = 0;
let testsFailed = 0;

function assertTrue(condition, message) {
  if (!condition) {
    console.error(`❌ ${message}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

console.log('\n╔════════════════════════════════════════════╗');
console.log('║  Design Compiler 테스트                   ║');
console.log('╚════════════════════════════════════════════╝\n');

try {
  console.log('📝 Test 1: 디자인 블록 추출');
  const compiler = new DesignCompiler();

  const freeContent = `
@animation hover {
  duration: 200ms
  scale: 1 → 1.1
}

@glass {
  background: rgba(255,255,255,0.1)
}
`;

  const blocks = compiler._extractDesignBlocks(freeContent);
  assertTrue(blocks.length > 0, '블록 추출됨');
  assertTrue(blocks.some(b => b.type === 'animation'), 'animation 블록');

  console.log('✅ Test 1 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

try {
  console.log('📝 Test 2: @animation 컴파일');
  const compiler = new DesignCompiler();

  const result = compiler.compileDesignBlocks(`
@animation slideIn {
  duration: 300ms
  translate: 0 20px → 0 0
}
`);

  assertTrue(result.css.includes('@keyframes'), '@keyframes 생성됨');

  console.log('✅ Test 2 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

try {
  console.log('📝 Test 3: @glass 컴파일');
  const compiler = new DesignCompiler();

  const result = compiler.compileDesignBlocks(`
@glass {
  background: rgba(255,255,255,0.1)
  backdropFilter: blur(10px)
}
`);

  assertTrue(result.css.includes('.glass-'), '.glass 클래스');

  console.log('✅ Test 3 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

try {
  console.log('📝 Test 4: 모든 엔진 통합');
  const compiler = new DesignCompiler();

  const freeContent = `
@animation fade { duration: 300ms opacity: 0 → 1 }
@glass { background: rgba(255,255,255,0.1) }
@3d { perspective: 1000 rotateY: 20deg }
@micro { event: click action: pulse }
@scroll { selector: .box animation: slideIn }
`;

  const result = compiler.compileDesignBlocks(freeContent);

  assertTrue(result.css.length > 0, 'CSS 생성됨');
  assertTrue(result.javascript.length > 0, 'JavaScript 생성됨');

  const stats = compiler.getStats();
  assertTrue(stats.animations.totalAnimations >= 1, 'animation 통계');

  console.log('✅ Test 4 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

console.log('╔════════════════════════════════════════════╗');
console.log(`║  Test 결과: ${testsPassed}/4 통과               ║`);
console.log('╚════════════════════════════════════════════╝\n');

if (testsFailed === 0) {
  console.log('🎉 모든 테스트 통과!\n');
  process.exit(0);
} else {
  console.log(`❌ ${testsFailed}개 테스트 실패\n`);
  process.exit(1);
}
EOF

