   * Read next character
   */
  private readChar(): void {
    if (this.position >= this.input.length) {
      this.current = '\0';
    } else {
      this.current = this.input[this.position];
    }
    this.position++;
    this.column++;
  }

  /**
   * Peek at next character without consuming
   */
  private peekChar(): string {
    if (this.position >= this.input.length) {
      return '\0';
    }
    return this.input[this.position];
  }

  /**
   * Skip whitespace
   */
  private skipWhitespace(): void {
    while (this.current === ' ' || this.current === '\t' || this.current === '\r') {
      this.readChar();
    }
  }

  /**
   * Skip single-line comment
   */
  private skipComment(): void {
    // Skip //
    this.readChar();
    this.readChar();

    // Read until newline
    while (this.current !== '\n' && this.current !== '\0') {
      this.readChar();
    }
  }

  /**
   * Skip multi-line comment
   */
  private skipMultiLineComment(): void {
    // Skip /*
    this.readChar();
    this.readChar();

    while (true) {
      if (this.current === '\0') {
        break;
      }

      if (this.current === '\n') {
        this.line++;
        this.column = 0;
      }

      if (this.current === '*' && this.peekChar() === '/') {
        this.readChar(); // *
        this.readChar(); // /
        break;
      }

      this.readChar();
    }
  }

  /**
   * Read identifier or keyword
   */
  private readIdentifier(): string {
    const start = this.position - 1;
    while (this.isIdentifierChar(this.current)) {
      this.readChar();
    }
    return this.input.substring(start, this.position - 1);
  }

  /**
   * Read number
   */
  private readNumber(): string {
    const start = this.position - 1;

    // Integer part
    while (this.isDigit(this.current)) {
      this.readChar();
    }

    // Decimal part
