const DesignCompiler = require('./design-compiler');

let testsPassed = 0;
let testsFailed = 0;

function assertTrue(condition, message) {
  if (!condition) {
    console.error(`❌ ${message}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

console.log('\n╔════════════════════════════════════════════╗');
console.log('║  Design Compiler 테스트                   ║');
console.log('╚════════════════════════════════════════════╝\n');

try {
  console.log('📝 Test 1: 디자인 블록 추출');
  const compiler = new DesignCompiler();

  const freeContent = `
@animation hover {
  duration: 200ms
  scale: 1 → 1.1
}

@glass {
  background: rgba(255,255,255,0.1)
}
`;

  const blocks = compiler._extractDesignBlocks(freeContent);
  assertTrue(blocks.length > 0, '블록 추출됨');
  assertTrue(blocks.some(b => b.type === 'animation'), 'animation 블록');

  console.log('✅ Test 1 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

try {
  console.log('📝 Test 2: @animation 컴파일');
  const compiler = new DesignCompiler();

  const result = compiler.compileDesignBlocks(`
@animation slideIn {
  duration: 300ms
  translate: 0 20px → 0 0

/**
 * Check if character can be part of identifier
 */
private isIdentifierChar(ch: string): boolean {
  return this.isLetter(ch) || this.isDigit(ch);
}

/**
 * Phase 10: Check if TokenType is a design directive
 */
private isDesignDirective(type: TokenType): boolean {
  return type === TokenType.ANIMATION_DESIGN ||
         type === TokenType.GLASS_DESIGN ||
         type === TokenType.TRANSFORM3D_DESIGN ||
         type === TokenType.MICRO_DESIGN ||
         type === TokenType.SCROLL_DESIGN;
}

/**
 * Create token and track last token type
 */
private makeToken(type: TokenType, value: string): Token {
  this.lastTokenType = type;
  return {
    type,
    value,
    line: this.line,
    column: this.column - value.length
  };
}

/**
 * Check if regex literal can appear in current context
 * Regex can follow: =, (, [, {, return, throw, :, ,, ;, &&, ||, !, ?, etc.
 */
private isRegexContext(): boolean {
  // Regex can appear at start or after certain token types
  switch (this.lastTokenType) {
    // After assignment/operators
    case TokenType.ASSIGN:
    case TokenType.PLUS_ASSIGN:
    case TokenType.MINUS_ASSIGN:
    case TokenType.STAR_ASSIGN:
    case TokenType.SLASH_ASSIGN:
    case TokenType.PERCENT_ASSIGN:
