// Pattern 타입 (Phase 2: Result/Option 패턴 추가)
export type Pattern =
  | LiteralPattern
  | VariablePattern
  | WildcardPattern
  | StructPattern
  | ArrayPattern
  | OkPattern
  | ErrPattern
  | SomePattern
  | NonePattern;

