 */

import {
  cacheNew,
  cacheGet,
  cacheSet,
  cacheInvalidate,
  cacheGetStats,
  cacheGetHitRate,
  cacheGetEvictionRate,
  CacheConfig,
  CacheStats,
  QueryCache
