/**
 * Run all Phase 12 benchmarks
 */
fn runAllPhase12Benchmarks() -> BenchmarkSuite12 {
  let results: [BenchmarkResult12] = []

  let b1: BenchmarkResult12 = benchmarkWalThroughput()
  results.push(b1)

  let b2: BenchmarkResult12 = benchmarkFtsVsLike()
  results.push(b2)

  let b3: BenchmarkResult12 = benchmarkReplicaLag()
  results.push(b3)

  let b4: BenchmarkResult12 = benchmarkLockOverhead()
  results.push(b4)

  let b5: BenchmarkResult12 = benchmarkVacuumEfficiency()
  results.push(b5)

  let b6: BenchmarkResult12 = benchmarkRestApiThroughput()
  results.push(b6)

  let b7: BenchmarkResult12 = benchmarkCsvMigration()
  results.push(b7)

  let b8: BenchmarkResult12 = benchmarkFullStack()
  results.push(b8)

  let totalDuration: f64 = 0.0
  let i: i32 = 0
  while i < results.length {
    totalDuration = totalDuration + results[i].totalTime
    i = i + 1
  }

  return {
    name: "Phase 12: Complete Benchmark Suite",
    results: results,
    totalDuration: totalDuration
  }
}

